/// This information is currently necessary, as the front-end has a difficult
/// time finding a specific cookie. With this, we can convey specific error
/// information without the cookie.
#[derive(Clone, Debug, serde::Serialize, serde::Deserialize)]
pub struct AuditsCookieIssueDetails {
    /// If AffectedCookie is not set then rawCookieLine contains the raw
    /// Set-Cookie header string. This hints at a problem where the
    /// cookie line is syntactically or semantically malformed in a way
    /// that no valid cookie could be created.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub cookie: Option<AuditsAffectedCookie>,
    #[serde(rename = "rawCookieLine")]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub raw_cookie_line: Option<String>,
    #[serde(rename = "cookieWarningReasons")]
    pub cookie_warning_reasons: Vec<AuditsCookieWarningReason>,
    #[serde(rename = "cookieExclusionReasons")]
    pub cookie_exclusion_reasons: Vec<AuditsCookieExclusionReason>,
    /// Optionally identifies the site-for-cookies and the cookie url, which
    /// may be used by the front-end as additional context.
    pub operation: AuditsCookieOperation,
    #[serde(rename = "siteForCookies")]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub site_for_cookies: Option<String>,
    #[serde(rename = "cookieUrl")]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub cookie_url: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub request: Option<AuditsAffectedRequest>,
    /// The recommended solution to the issue.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub insight: Option<AuditsCookieIssueInsight>,
}

impl AuditsCookieIssueDetails {
    /// Construct with all required fields; optional fields default to `None`
    /// and any open-object extra map defaults to `Default::default()`.
    pub fn new(cookie_warning_reasons: Vec<AuditsCookieWarningReason>, cookie_exclusion_reasons: Vec<AuditsCookieExclusionReason>, operation: AuditsCookieOperation) -> Self {
        Self {
            cookie: None,
            raw_cookie_line: None,
            cookie_warning_reasons,
            cookie_exclusion_reasons,
            operation,
            site_for_cookies: None,
            cookie_url: None,
            request: None,
            insight: None,
        }
    }
}

