/// Players will get an ID that is unique within the agent context.
pub type MediaPlayerId = String;

/// Keep in sync with MediaLogMessageLevel
/// We are currently keeping the message level 'error' separate from the
/// PlayerError type because right now they represent different things,
/// this one being a DVLOG(ERROR) style log message that gets printed
/// based on what log level is selected in the UI, and the other is a
/// representation of a media::PipelineStatus object. Soon however we're
/// going to be moving away from using PipelineStatus for errors and
/// introducing a new error type which should hopefully let us integrate
/// the error log level into the PlayerError type.
#[derive(Clone, Debug, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub enum MediaPlayerMessageLevel {
    #[serde(rename = "error")]
    Error,
    #[serde(rename = "warning")]
    Warning,
    #[serde(rename = "info")]
    Info,
    #[serde(rename = "debug")]
    Debug,
}

/// Have one type per entry in MediaLogRecord::Type
/// Corresponds to kMessage
#[derive(Clone, Debug, serde::Serialize, serde::Deserialize)]
pub struct MediaPlayerMessage {
    /// Keep in sync with MediaLogMessageLevel
    /// We are currently keeping the message level 'error' separate from the
    /// PlayerError type because right now they represent different things,
    /// this one being a DVLOG(ERROR) style log message that gets printed
    /// based on what log level is selected in the UI, and the other is a
    /// representation of a media::PipelineStatus object. Soon however we're
    /// going to be moving away from using PipelineStatus for errors and
    /// introducing a new error type which should hopefully let us integrate
    /// the error log level into the PlayerError type.
    pub level: MediaPlayerMessageLevel,
    pub message: String,
}

impl MediaPlayerMessage {
    /// Construct with all required fields; optional fields default to `None`
    /// and any open-object extra map defaults to `Default::default()`.
    pub fn new(level: MediaPlayerMessageLevel, message: String) -> Self {
        Self {
            level,
            message,
        }
    }
}

