/// Cookie object
#[derive(Clone, Debug, serde::Serialize, serde::Deserialize)]
pub struct NetworkCookie {
    /// Cookie name.
    pub name: String,
    /// Cookie value.
    pub value: String,
    /// Cookie domain.
    pub domain: String,
    /// Cookie path.
    pub path: String,
    /// Cookie expiration date as the number of seconds since the UNIX epoch.
    /// The value is set to -1 if the expiry date is not set.
    /// The value can be null for values that cannot be represented in
    /// JSON (±Inf).
    pub expires: f64,
    /// Cookie size.
    pub size: i64,
    /// True if cookie is http-only.
    #[serde(rename = "httpOnly")]
    pub http_only: bool,
    /// True if cookie is secure.
    pub secure: bool,
    /// True in case of session cookie.
    pub session: bool,
    /// Cookie SameSite type.
    #[serde(rename = "sameSite")]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub same_site: Option<NetworkCookieSameSite>,
    /// Cookie Priority
    pub priority: NetworkCookiePriority,
    /// Cookie source scheme type.
    #[serde(rename = "sourceScheme")]
    pub source_scheme: NetworkCookieSourceScheme,
    /// Cookie source port. Valid values are {-1, [1, 65535]}, -1 indicates an unspecified port.
    /// An unspecified port value allows protocol clients to emulate legacy cookie scope for the port.
    /// This is a temporary ability and it will be removed in the future.
    #[serde(rename = "sourcePort")]
    pub source_port: i64,
    /// Cookie partition key.
    #[serde(rename = "partitionKey")]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub partition_key: Option<NetworkCookiePartitionKey>,
    /// True if cookie partition key is opaque.
    #[serde(rename = "partitionKeyOpaque")]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub partition_key_opaque: Option<bool>,
}

impl NetworkCookie {
    /// Construct with all required fields; optional fields default to `None`
    /// and any open-object extra map defaults to `Default::default()`.
    pub fn new(name: String, value: String, domain: String, path: String, expires: f64, size: i64, http_only: bool, secure: bool, session: bool, priority: NetworkCookiePriority, source_scheme: NetworkCookieSourceScheme, source_port: i64) -> Self {
        Self {
            name,
            value,
            domain,
            path,
            expires,
            size,
            http_only,
            secure,
            session,
            same_site: None,
            priority,
            source_scheme,
            source_port,
            partition_key: None,
            partition_key_opaque: None,
        }
    }
}

