/// An object representing a report generated by the Reporting API.
#[derive(Clone, Debug, serde::Serialize, serde::Deserialize)]
pub struct NetworkReportingApiReport {
    pub id: NetworkReportId,
    /// The URL of the document that triggered the report.
    #[serde(rename = "initiatorUrl")]
    pub initiator_url: String,
    /// The name of the endpoint group that should be used to deliver the report.
    pub destination: String,
    /// The type of the report (specifies the set of data that is contained in the report body).
    pub r#type: String,
    /// When the report was generated.
    pub timestamp: NetworkTimeSinceEpoch,
    /// How many uploads deep the related request was.
    pub depth: i64,
    /// The number of delivery attempts made so far, not including an active attempt.
    #[serde(rename = "completedAttempts")]
    pub completed_attempts: i64,
    pub body: std::collections::HashMap<String, serde_json::Value>,
    pub status: NetworkReportStatus,
}

impl NetworkReportingApiReport {
    /// Construct with all required fields; optional fields default to `None`
    /// and any open-object extra map defaults to `Default::default()`.
    pub fn new(id: NetworkReportId, initiator_url: String, destination: String, r#type: String, timestamp: NetworkTimeSinceEpoch, depth: i64, completed_attempts: i64, body: std::collections::HashMap<String, serde_json::Value>, status: NetworkReportStatus) -> Self {
        Self {
            id,
            initiator_url,
            destination,
            r#type,
            timestamp,
            depth,
            completed_attempts,
            body,
            status,
        }
    }
}

