/// Corresponds to SpeculationRuleSet
#[derive(Clone, Debug, serde::Serialize, serde::Deserialize)]
pub struct PreloadRuleSet {
    pub id: PreloadRuleSetId,
    /// Identifies a document which the rule set is associated with.
    #[serde(rename = "loaderId")]
    pub loader_id: NetworkLoaderId,
    /// Source text of JSON representing the rule set. If it comes from
    /// `<script>` tag, it is the textContent of the node. Note that it is
    /// a JSON for valid case.
    ///
    /// See also:
    /// - https://wicg.github.io/nav-speculation/speculation-rules.html
    /// - https://github.com/WICG/nav-speculation/blob/main/triggers.md
    #[serde(rename = "sourceText")]
    pub source_text: String,
    /// A speculation rule set is either added through an inline
    /// `<script>` tag or through an external resource via the
    /// 'Speculation-Rules' HTTP header. For the first case, we include
    /// the BackendNodeId of the relevant `<script>` tag. For the second
    /// case, we include the external URL where the rule set was loaded
    /// from, and also RequestId if Network domain is enabled.
    ///
    /// See also:
    /// - https://wicg.github.io/nav-speculation/speculation-rules.html#speculation-rules-script
    /// - https://wicg.github.io/nav-speculation/speculation-rules.html#speculation-rules-header
    #[serde(rename = "backendNodeId")]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub backend_node_id: Option<DomBackendNodeId>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub url: Option<String>,
    #[serde(rename = "requestId")]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub request_id: Option<NetworkRequestId>,
    /// Error information
    /// `errorMessage` is null iff `errorType` is null.
    #[serde(rename = "errorType")]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub error_type: Option<PreloadRuleSetErrorType>,
    /// TODO(https://crbug.com/1425354): Replace this property with structured error.
    #[serde(rename = "errorMessage")]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub error_message: Option<String>,
    /// For more details, see:
    /// https://github.com/WICG/nav-speculation/blob/main/speculation-rules-tags.md
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tag: Option<String>,
}

impl PreloadRuleSet {
    /// Construct with all required fields; optional fields default to `None`
    /// and any open-object extra map defaults to `Default::default()`.
    pub fn new(id: PreloadRuleSetId, loader_id: NetworkLoaderId, source_text: String) -> Self {
        Self {
            id,
            loader_id,
            source_text,
            backend_node_id: None,
            url: None,
            request_id: None,
            error_type: None,
            error_message: None,
            tag: None,
        }
    }
}

